#include <freerdp/server/cliprdr.h>
#include <freerdp/channels/channels.h>
#include <freerdp/channels/wtsvc.h>
#include <winpr/wtsapi.h>
#include <winpr/clipboard.h>
#include <openssl/evp.h>
static CliprdrServerContext* clipboardServer;static HANDLE clipboardManager;static const char* clipboardMode;static int clipboardActivated;
static UINT fixture_formats(CliprdrServerContext* context){CLIPRDR_FORMAT format={.formatId=strstr(clipboardMode,"unsupported")?CF_TEXT:CF_UNICODETEXT};CLIPRDR_FORMAT_LIST list={.numFormats=1,.formats=&format};return context->ServerFormatList(context,&list);}
static UINT fixture_caps(CliprdrServerContext* context,const CLIPRDR_CAPABILITIES* caps){(void)caps;note("{\"type\":\"clipReady\"}");return fixture_formats(context);}
static UINT fixture_list_ack(CliprdrServerContext* context,const CLIPRDR_FORMAT_LIST_RESPONSE* response){(void)context;(void)response;return CHANNEL_RC_OK;}
static UINT fixture_list(CliprdrServerContext* context,const CLIPRDR_FORMAT_LIST* list){note("{\"type\":\"clipOffer\"}");if(strstr(clipboardMode,"offer-timeout"))return CHANNEL_RC_OK;CLIPRDR_FORMAT_LIST_RESPONSE response={.common.msgFlags=strstr(clipboardMode,"reject")?CB_RESPONSE_FAIL:CB_RESPONSE_OK};UINT rc=context->ServerFormatListResponse(context,&response);if(rc||response.common.msgFlags==CB_RESPONSE_FAIL)return rc;for(UINT32 i=0;i<list->numFormats;i++){if(list->formats[i].formatId==CF_UNICODETEXT){CLIPRDR_FORMAT_DATA_REQUEST request={.requestedFormatId=CF_UNICODETEXT};return context->ServerFormatDataRequest(context,&request);}}return CHANNEL_RC_OK;}
static UINT fixture_read(CliprdrServerContext* context,const CLIPRDR_FORMAT_DATA_REQUEST* request){note("{\"type\":\"clipRead\"}");if(strstr(clipboardMode,"read-timeout"))return CHANNEL_RC_OK;if(request->requestedFormatId!=CF_UNICODETEXT)return ERROR_INVALID_DATA;BYTE normal[]={'r',0,'e',0,'m',0,'o',0,'t',0,'e',0,' ',0,0x2d,0x4e,0x87,0x65,' ',0,0x3d,0xd8,0,0xde,13,0,10,0,0,0};BYTE malformed[]={0,0xd8,0,0};BYTE* allocated=NULL;const BYTE* data=normal;size_t length=sizeof(normal);
 if(strstr(clipboardMode,"large")||strstr(clipboardMode,"oversize")||strstr(clipboardMode,"bomb")){size_t units=strstr(clipboardMode,"bomb")?1500000:1048576+(strstr(clipboardMode,"oversize")?1:0);length=units*2+2;allocated=calloc(length,1);if(!allocated)return CHANNEL_RC_NO_MEMORY;for(size_t i=0;i<units;i++)allocated[i*2]='a';data=allocated;}
 if(strstr(clipboardMode,"bad")){data=malformed;length=sizeof(malformed);}if(strstr(clipboardMode,"stale")){UINT rc=fixture_formats(context);if(rc){free(allocated);return rc;}}
 CLIPRDR_FORMAT_DATA_RESPONSE response={.common.msgFlags=CB_RESPONSE_OK,.common.dataLen=(UINT32)length,.requestedFormatData=data};UINT rc=context->ServerFormatDataResponse(context,&response);free(allocated);return rc;
}
static UINT fixture_received(CliprdrServerContext* context,const CLIPRDR_FORMAT_DATA_RESPONSE* response){(void)context;size_t count=response->common.dataLen;if(count>2097154)return ERROR_INVALID_DATA;char* encoded=calloc(4*((count+2)/3)+1,1);if(!encoded)return CHANNEL_RC_NO_MEMORY;EVP_EncodeBlock((unsigned char*)encoded,response->requestedFormatData,(int)count);fprintf(events,"{\"type\":\"clipReceived\",\"flags\":%u,\"data\":\"%s\"}\n",response->common.msgFlags,encoded);fflush(events);free(encoded);return CHANNEL_RC_OK;}
static BOOL fixture_clipboard_start(freerdp_peer* peer){if(!clipboardMode||!clipboardActivated||clipboardServer)return TRUE;if(!WTSVirtualChannelManagerIsChannelJoined(clipboardManager,CLIPRDR_SVC_CHANNEL_NAME)){note("{\"type\":\"clipNotJoined\"}");return TRUE;}note("{\"type\":\"clipStarting\"}");clipboardServer=cliprdr_server_context_new(clipboardManager);if(!clipboardServer)return FALSE;clipboardServer->rdpcontext=peer->context;clipboardServer->autoInitializationSequence=TRUE;clipboardServer->useLongFormatNames=TRUE;clipboardServer->streamFileClipEnabled=FALSE;clipboardServer->canLockClipData=FALSE;clipboardServer->ClientCapabilities=fixture_caps;clipboardServer->ClientFormatList=fixture_list;clipboardServer->ClientFormatListResponse=fixture_list_ack;clipboardServer->ClientFormatDataRequest=fixture_read;clipboardServer->ClientFormatDataResponse=fixture_received;return clipboardServer->Start(clipboardServer)==CHANNEL_RC_OK;}
